function allowedActions(lot: Lot) {
  let actions: string[];
  if (lot.status === 'draft') actions = ['publish', 'archive'];
  else if (lot.status === 'mirrored') actions = ['reset', 'archive'];
  else if (lot.status === 'scheduled') actions = ['pause', 'extend', 'end', 'reset', 'archive'];
  else if (lot.status === 'open') actions = [lot.acceptsBids?'disable-bids':'enable-bids','pause', 'extend', 'end'];
  else if (lot.status === 'paused') actions = ['resume', 'extend', 'end', 'reset', 'archive'];
  else if (lot.status === 'ended') actions = ['extend', 'resume', 'reset', 'archive'];
  else if (lot.status === 'pending' || lot.status === 'cancelled') actions = ['reset', 'archive'];
  else actions = lot.status === 'archived' || lot.status === 'sold' ? [] : ['archive'];
  return lot.status === 'sold' ? actions : [...actions, 'delete'];
}

