function ActionModal({ lot, action, close }: { lot: Lot; action: string; close: () => void }) {
  const { run, busy } = useAdmin(); const [minutes, setMinutes] = useState('60'), [confirmation,setConfirmation]=useState(''); const deleting=action==='delete', confirmed=confirmation.trim().toUpperCase()==='EXCLUIR';
  return <Modal title={actionNames[action]} onClose={close}><p><b>{lot.title}</b></p>{action === 'end' && <p className="lab-note">O lote ficará aguardando decisão. Nenhum vencedor ou cobrança será criado automaticamente.</p>}{action === 'reset' && <p className="lab-note">Será aberta uma nova rodada em rascunho. O histórico anterior permanece preservado.</p>}{deleting&&<p className="lab-note danger">Esta exclusão é irreversível e remove o produto, galeria, relatórios, lances e cobranças ainda não liquidadas. Pagamentos já liquidados bloqueiam a exclusão.</p>}<form onSubmit={async (event) => { event.preventDefault(); const result = deleting ? await run(`/v1/auction/admin/lots/${lot.id}`, { method: 'DELETE' }, 'Produto e todo o conteúdo relacionado foram excluídos.') : await run(`/v1/auction/admin/lots/${lot.id}/action`, { method: 'POST', body: { action, minutes: Number(minutes) } }, 'Ação registrada na auditoria.'); if (result) close(); }}>{action === 'extend' && <Field label="Acrescentar minutos"><input type="number" min="1" max="43200" required value={minutes} onChange={(event) => setMinutes(event.target.value)}/></Field>}{deleting&&<Field label="Digite EXCLUIR para confirmar"><input value={confirmation} onChange={(event)=>setConfirmation(event.target.value)} autoComplete="off" autoFocus required/></Field>}<div className="lab-modal-actions"><button type="button" className="lab-outline-button" onClick={close}>Voltar</button><button type="submit" className={deleting?'lab-danger-button':'lab-button'} disabled={busy||(deleting&&!confirmed)}>{busy?'Processando…':deleting?'Excluir tudo':'Confirmar'}</button></div></form></Modal>;
}

function mergePresentation(lot:Lot,item:Record<string,any>):Lot{
  return {...lot,description:String(item.description??''),imageUrl:String(item.image_url??''),mediaUrls:Array.isArray(item.media_urls)?item.media_urls.map(String):[],mediaCount:Number(item.media_count??0),providerName:String(item.provider_name??''),locationLabel:String(item.location_label??''),latitude:item.latitude==null?null:Number(item.latitude),longitude:item.longitude==null?null:Number(item.longitude),detailData:item.detail_data&&typeof item.detail_data==='object'?item.detail_data:{},documents:(item.documents??[]).map((document:Record<string,any>)=>({id:String(document.id),title:String(document.title??''),url:String(document.url??''),documentType:String(document.document_type??'attachment'),position:Number(document.position??0)}))};
}

function LotEditor({ lot, editing }: { lot?: Lot; editing: boolean }) {
  const { dashboard, run, busy, flash } = useAdmin(); const router = useRouter();
  const [fullLot,setFullLot]=useState<Lot|undefined>(editing?undefined:lot),[loadingFull,setLoadingFull]=useState(Boolean(editing&&lot)),[loadFailed,setLoadFailed]=useState(false);
  const [depositPercent, setDepositPercent] = useState(String((lot?.depositBps ?? 2000) / 100));
  const [minimumLimit, setMinimumLimit] = useState(String((lot?.minimumLimit ?? 0) / 100));
  const [minimumDeposit, setMinimumDeposit] = useState(String((lot?.minimumDeposit ?? 0) / 100));
  const [example, setExample] = useState('5000');
  async function loadPresentation(showError=true){
    if(!lot)return;
    setLoadingFull(true);setLoadFailed(false);
    try{const {lot:item}=await api<{lot:Record<string,any>}>(`/v1/auction/admin/lots/${lot.id}/presentation`);setFullLot(mergePresentation(lot,item));}
    catch(error){setLoadFailed(true);if(showError)flash(error instanceof Error?error.message:'Não foi possível carregar o produto completo.',true);}
    finally{setLoadingFull(false);}
  }
  useEffect(()=>{if(lot)void loadPresentation();},[lot?.id]);
  const editorLot=lot?fullLot:undefined;
  let exampleDeposit = 0; try { exampleDeposit = collateral(aedMinor(example), Math.round(Number(depositPercent) * 100), aedMinor(minimumLimit), aedMinor(minimumDeposit)); } catch {}
  async function submit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const form = new FormData(event.currentTarget), get = (name: string) => String(form.get(name) ?? '');
    try {
      const documents=get('documents').split('\n').map((line)=>line.split('|').map((part)=>part.trim())).filter((parts)=>parts[0]&&parts[1]).map(([title,url])=>({title,url,documentType:url.toLowerCase().includes('.pdf')?'pdf':'attachment'}));
      const detailData=JSON.parse(get('detailData')||'{}') as Record<string,unknown>;
      const body = { title: get('title'), category: get('category'), description: get('description'), imageUrl: get('imageUrl'), imageUrls: get('imageUrls').split('\n').map((value)=>value.trim()).filter(Boolean), providerName:get('providerName'),locationLabel:get('locationLabel'),latitude:get('latitude')?Number(get('latitude')):null,longitude:get('longitude')?Number(get('longitude')):null,detailData,documents, mode: get('mode'), bidCount:Number(get('bidCount')), startPriceMinor: aedMinor(get('startPrice')), incrementMinor: aedMinor(get('increment')), extensionMinutes: Number(get('extensionMinutes')), feeMinor: aedMinor(get('fee')), feeRules: [], vatBps: Math.round(Number(get('vatPercent')) * 100), depositBps: Math.round(Number(depositPercent) * 100), minimumDepositMinor: aedMinor(minimumDeposit), minimumLimitMinor: aedMinor(minimumLimit), depositUsage: get('depositUsage'),shipmentFeeMinor:aedMinor(get('shipmentFee')),ownershipFeeMinor:aedMinor(get('ownershipFee')),checkoutTtlMinutes:Number(get('checkoutTtlMinutes')), startsAt: new Date(get('startsAt')).toISOString(), endsAt: new Date(get('endsAt')).toISOString() };
      const result = await run(lot ? `/v1/auction/admin/lots/${lot.id}` : '/v1/auction/admin/lots', { method: lot ? 'PUT' : 'POST', body }, lot ? 'Produto atualizado.' : 'Produto criado como rascunho.');
      if (result) router.push(url('painel/leiloes'));
    } catch (error) { flash((error as Error).message, true); }
  }
  if (editing && !lot) return <Empty>Produto não encontrado.</Empty>;
  if (loadingFull) return <><Section title="Editar produto / leilão" eyebrow={lot ? `RODADA ${lot.round}` : 'PRODUTO'}/><div className="lab-panel"><p>Carregando galeria, documentos e regras completas…</p></div></>;
  if (lot && (!editorLot || loadFailed)) return <><Section title="Editar produto / leilão" eyebrow={`RODADA ${lot.round}`}/><div className="lab-panel"><p>Não foi possível carregar o produto completo com segurança.</p><button type="button" className="lab-button" onClick={()=>loadPresentation()}>Tentar novamente</button></div></>;
  return <><Section title={lot ? 'Editar produto / leilão' : 'Cadastrar produto / leilão'} eyebrow={lot ? `RODADA ${lot.round}` : 'NOVO RASCUNHO'} actions={lot && <><a className="lab-outline-button" href={publicLotUrl(lot.id)} target="_blank" rel="noreferrer">Abrir página pública ↗</a><Badge value={lot.status}/></>}/>{lot&&lot.status!=='draft'&&<p className="lab-note">Este lote está publicado, mas continua editável. Lances reais e o preço vigente são preservados; toda alteração fica registrada na auditoria.</p>}
    <form onSubmit={submit}><div className="lab-panel"><div className="lab-inline-head"><h2>Produto e apresentação</h2>{lot&&editorLot?.sourceUrl&&<button type="button" className="lab-outline-button small" disabled={busy} onClick={async()=>{const result=await run(`/v1/auction/admin/lots/${lot.id}/sync-source`,{method:'POST',body:{}},'Conteúdo sincronizado da V1.');if(result)await loadPresentation(false);}}>Sincronizar fonte V1</button>}</div><Field label="Título"><input name="title" required maxLength={180} defaultValue={editorLot?.title}/></Field><div className="lab-form-grid"><Field label="Categoria"><select name="category" defaultValue={editorLot?.category ?? dashboard!.categories[0]?.title}>{dashboard!.categories.map((item) => <option key={item.id}>{item.title}</option>)}</select></Field><Field label="Modalidade"><select name="mode" defaultValue={editorLot?.mode ?? 'auction'}><option value="auction">Leilão</option><option value="direct">Compra direta</option></select></Field></div><Field label="Descrição"><textarea name="description" maxLength={30000} rows={7} defaultValue={editorLot?.description}/></Field><Field label="URL da imagem principal"><input name="imageUrl" type="url" maxLength={1500} defaultValue={editorLot?.imageUrl}/></Field><Field label="Galeria de imagens" hint="Uma URL HTTPS por linha, em ordem. Até 500 fotos por produto."><textarea name="imageUrls" rows={9} defaultValue={(editorLot?.mediaUrls.length?editorLot.mediaUrls:[editorLot?.imageUrl].filter(Boolean)).join('\n')}/></Field><div className="lab-form-grid"><Field label="Fornecedor"><input name="providerName" maxLength={180} defaultValue={editorLot?.providerName}/></Field><Field label="Local / endereço"><input name="locationLabel" maxLength={300} defaultValue={editorLot?.locationLabel}/></Field><Field label="Latitude"><input name="latitude" inputMode="decimal" defaultValue={editorLot?.latitude??''}/></Field><Field label="Longitude"><input name="longitude" inputMode="decimal" defaultValue={editorLot?.longitude??''}/></Field></div><Field label="Documentos" hint="Título | URL HTTPS, um por linha"><textarea name="documents" rows={5} defaultValue={editorLot?.documents.map((document)=>`${document.title} | ${document.url??''}`).join('\n')}/></Field><Field label="Especificações estruturadas (JSON)"><textarea className="lab-code-input" name="detailData" rows={9} defaultValue={JSON.stringify(editorLot?.detailData??{},null,2)}/></Field></div>
      <div className="lab-panel"><h2>Valores, lances e calendário</h2><div className="lab-form-grid"><Field label="Valor inicial / preço (AED)"><input name="startPrice" required defaultValue={(editorLot?.startPrice ?? 100000) / 100}/></Field><Field label="Incremento mínimo (AED)"><input name="increment" type="number" min="100" step="1" required defaultValue={(editorLot?.increment ?? 10000) / 100}/></Field><Field label="Quantidade exibida de lances" hint="Inclui os lances reais. Não cria nem apaga registros de usuários."><input name="bidCount" type="number" min="0" max="1000000" step="1" required defaultValue={editorLot?.bidCount??0}/></Field><Field label="Taxa administrativa fixa (AED)"><input name="fee" required defaultValue={(editorLot?.fee ?? 0) / 100}/></Field><Field label="VAT / tributo (%)"><input name="vatPercent" required defaultValue={(editorLot?.vatBps ?? 500) / 100}/></Field><Field label="Início"><input name="startsAt" type="datetime-local" required defaultValue={localDate(editorLot?.startsAt ?? Date.now())}/></Field><Field label="Fim"><input name="endsAt" type="datetime-local" required defaultValue={localDate(editorLot?.endsAt ?? Date.now() + 86400000)}/></Field><Field label="Prorrogação automática por lance (min)"><input name="extensionMinutes" type="number" min="1" max="60" required defaultValue={editorLot?.extensionMinutes ?? 3}/></Field></div></div>
      <div className="lab-panel"><div className="lab-inline-head"><h2>Compra direta</h2><span className="lab-badge">Checkout de placas</span></div><div className="lab-form-grid"><Field label="Frete / entrega (AED)"><input name="shipmentFee" required defaultValue={(editorLot?.shipmentFee??5300)/100}/></Field><Field label="Transferência de propriedade (AED)"><input name="ownershipFee" required defaultValue={(editorLot?.ownershipFee??10000)/100}/></Field><Field label="Expiração do carrinho (min)"><input name="checkoutTtlMinutes" type="number" min="5" max="120" required defaultValue={editorLot?.checkoutTtlMinutes??15}/></Field></div><p className="lab-fine">Aplicado somente a produtos em modalidade Compra direta. O total inclui preço, taxa administrativa, entrega, propriedade e VAT.</p></div>
      <div className="lab-panel"><div className="lab-inline-head"><h2>Depósito e limite de lance</h2><span className="lab-badge">Variável por lote</span></div><div className="lab-form-grid"><Field label="Percentual exigido (%)"><input required value={depositPercent} onChange={(event) => setDepositPercent(event.target.value)}/></Field><Field label="Base mínima do limite (AED)" hint="Ex.: limite-base 5.000 a 20% exige 1.000."><input required value={minimumLimit} onChange={(event) => setMinimumLimit(event.target.value)}/></Field><Field label="Depósito mínimo absoluto (AED)"><input required value={minimumDeposit} onChange={(event) => setMinimumDeposit(event.target.value)}/></Field><Field label="Uso do depósito"><select name="depositUsage" defaultValue={editorLot?.depositUsage ?? 'checkout_eligible'}><option value="checkout_eligible">Abate no checkout</option><option value="bidding_only">Somente garantia de lance</option></select></Field></div><div className="lab-rule-preview"><Field label="Simular limite (AED)"><input value={example} onChange={(event) => setExample(event.target.value)}/></Field><div><small>Depósito calculado</small><strong>{money(exampleDeposit)}</strong></div></div></div>
      <div className="lab-editor-actions"><Link className="lab-outline-button" href={url('painel/leiloes')}>Voltar</Link><button type="submit" className="lab-button" disabled={busy}>{busy?'Salvando…':'Salvar alterações'}</button></div></form></>;
}

